import type { Goal, GoalWithCalculations } from '@/lib/types';
import { FormSection } from './FormSection';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Trash2, PlusCircle, Target } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Table, TableBody, TableCell, TableRow } from '@/components/ui/table';
import { Label } from '../ui/label';

interface Props {
  goals: Goal[];
  setGoals: React.Dispatch<React.SetStateAction<Goal[]>>;
  goalsWithCalculations: GoalWithCalculations[];
}

const goalTypes = ["Child Education", "Marriage", "House", "Emergency Fund", "Wealth Accumulation", "Vacation Fund", "Vehicle Purchase", "Gadget/Technology Fund", "Other"];

let nextId = 0;

export function GoalsForm({ goals, setGoals, goalsWithCalculations }: Props) {

  const handleUpdate = (id: string, field: keyof Goal, value: string | number) => {
    setGoals(goals.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handleAdd = () => {
    const newGoal: Goal = { id: `new-${nextId++}`, name: '', corpus: '', years: '', rate: 12, currentSave: '', currentSip: '' };
    setGoals(prevGoals => [...prevGoals, newGoal]);
  };

  const handleRemove = (id: string) => {
    setGoals(goals.filter(item => item.id !== id));
  };

  const formatCurrency = (value: number) => {
    return `₹${value.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  }

  return (
    <FormSection
      title="Financial Goals"
      description="Plan your investments for future milestones."
      icon={<Target className="h-6 w-6" />}
      className="xl:col-span-2"
    >
      <div className="space-y-4">
        {goals.map((goal, index) => {
          const calcs = goalsWithCalculations[index];
          return (
            <div key={goal.id} className="p-4 border rounded-lg space-y-4 relative">
              <div className="absolute top-2 right-2">
                  <Button variant="ghost" size="icon" onClick={() => handleRemove(goal.id)} className="text-destructive h-7 w-7">
                    <Trash2 className="h-4 w-4" />
                  </Button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                <div className="space-y-1.5">
                  <label className="text-sm font-medium">Goal Name</label>
                  <Select
                    value={goal.name}
                    onValueChange={(value) => handleUpdate(goal.id, 'name', value)}
                  >
                    <SelectTrigger><SelectValue placeholder="Select goal" /></SelectTrigger>
                    <SelectContent>
                      {goalTypes.map(type => <SelectItem key={type} value={type}>{type}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
                 {goal.name === 'Other' && (
                  <div className="space-y-1.5 animate-in fade-in-50">
                    <Label htmlFor={`goal-other-${goal.id}`}>Please specify</Label>
                    <Input
                      id={`goal-other-${goal.id}`}
                      placeholder="e.g., World Tour"
                      value={goal.otherType || ''}
                      onChange={(e) => handleUpdate(goal.id, 'otherType', e.target.value)}
                    />
                  </div>
                )}
                <div className="space-y-1.5">
                  <label className="text-sm font-medium">Target Corpus (Today's Value)</label>
                  <Input
                    type="number"
                    placeholder="Amount (₹)"
                    value={goal.corpus}
                    onChange={(e) => handleUpdate(goal.id, 'corpus', e.target.value === '' ? '' : Number(e.target.value))}
                  />
                </div>
                 <div className="space-y-1.5">
                  <label className="text-sm font-medium">Years to Goal</label>
                  <Input
                    type="number"
                    placeholder="Time Horizon"
                    value={goal.years}
                    onChange={(e) => handleUpdate(goal.id, 'years', e.target.value === '' ? '' : Number(e.target.value))}
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-sm font-medium">Current Savings for Goal</label>
                  <Input
                    type="number"
                    placeholder="e.g. 100000"
                    value={goal.currentSave}
                    onChange={(e) => handleUpdate(goal.id, 'currentSave', e.target.value === '' ? '' : Number(e.target.value))}
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-sm font-medium">Current Monthly SIP</label>
                  <Input
                    type="number"
                    placeholder="e.g. 5000"
                    value={goal.currentSip}
                    onChange={(e) => handleUpdate(goal.id, 'currentSip', e.target.value === '' ? '' : Number(e.target.value))}
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-sm font-medium">Expected Return Rate (%)</label>
                  <Input
                    type="number"
                    placeholder="e.g., 12"
                    value={goal.rate}
                    onChange={(e) => handleUpdate(goal.id, 'rate', e.target.value === '' ? '' : Number(e.target.value))}
                  />
                </div>
              </div>

              {calcs && (
                <div className="bg-accent/10 p-3 rounded-md">
                   <h4 className="font-semibold text-accent-foreground/90 mb-2">Goal Projection</h4>
                   <Table>
                      <TableBody className="text-sm">
                        <TableRow>
                          <TableCell className="font-medium">Future Value of Goal (Inflated)</TableCell>
                          <TableCell className="text-right font-semibold">{formatCurrency(calcs.futureValueOfGoal)}</TableCell>
                        </TableRow>
                        <TableRow>
                          <TableCell className="font-medium">Future Value of Current Savings</TableCell>
                          <TableCell className="text-right font-semibold">{formatCurrency(calcs.futureValueOfCurrentSave)}</TableCell>
                        </TableRow>
                        <TableRow>
                          <TableCell className="font-medium">Future Value of Current SIP</TableCell>
                          <TableCell className="text-right font-semibold">{formatCurrency(calcs.futureValueOfSip)}</TableCell>
                        </TableRow>
                         <TableRow>
                          <TableCell className="font-medium">Total Projected Value</TableCell>
                          <TableCell className="text-right font-semibold">{formatCurrency(calcs.totalFutureValue)}</TableCell>
                        </TableRow>
                        <TableRow className="bg-accent/20">
                          <TableCell className="font-bold text-accent-foreground">Shortfall / Surplus</TableCell>
                          <TableCell className={`text-right font-bold ${calcs.shortfall < 0 ? 'text-destructive' : 'text-green-600'}`}>{formatCurrency(calcs.shortfall)}</TableCell>
                        </TableRow>
                      </TableBody>
                   </Table>
                   <div className="bg-accent/20 text-accent-foreground mt-3 p-3 rounded-md flex justify-between items-center">
                      <span className="font-semibold text-base">New Monthly SIP Required</span>
                      <Badge variant="secondary" className="text-lg font-bold bg-accent text-accent-foreground">
                          {formatCurrency(calcs.newSipRequired)}
                      </Badge>
                  </div>
                </div>
              )}
            </div>
          )
        })}
      </div>
      <Button variant="outline" size="sm" className="mt-4" onClick={handleAdd}>
        <PlusCircle className="mr-2 h-4 w-4" /> Add Goal
      </Button>
    </FormSection>
  );
}

src/components/planner/Planner.tsx.content:
"use client";

import { useState, useMemo, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import type { PersonalDetails, Asset, Liability, Income, Expense, Goal, GoalWithCalculations, SipOptimizerReportData, GoalWithSip, SipOptimizerGoal, InsuranceAnalysisData, WealthCreationGoal, ReportData, RetirementInputs, RetirementCalculations, AssetAllocationProfile, AllPlannerData, FundAllocation, LifeInsuranceQuote, HealthInsuranceQuote, RetirementGoalReport } from '@/lib/types';
import { calculateAge, calculateGoalDetails, calculateTimelines, calculateSip, calculateWealthCreation, calculateFutureValue, calculateRetirementDetails, calculateNper } from '@/lib/calculations';
import { Button } from '@/components/ui/button';
import { useToast } from '@/hooks/use-toast';
import { Loader2, Download, Eraser } from 'lucide-react';
import { generateCsv } from '@/lib/csv';
import { useAuth } from '@/context/AuthContext';

import { PersonalDetailsForm } from './PersonalDetailsForm';
import { AssetsLiabilitiesForm } from './AssetsLiabilitiesForm';
import { IncomeExpensesForm } from './IncomeExpensesForm';
import { InsuranceForm } from './InsuranceForm';
import { GoalsForm } from './GoalsForm';
import { EstatePlanningForm } from './EstatePlanningForm';
import { RetirementPlannerForm } from './RetirementPlannerForm';
import { AssetAllocationForm } from './AssetAllocationForm';
import { RecommendedFunds } from './RecommendedFunds';
import { GoalsBreakdown } from './GoalsBreakdown';
import { AppHeader } from '../layout/AppHeader';
import { InsuranceQuotesForm } from './InsuranceQuotesForm';


const initialPersonalDetails: PersonalDetails = { name: '', dob: '', dependents: '', retirementAge: '', mobile: '', email: '', arn: '' };
const initialAssets: Asset[] = [];
const initialLiabilities: Liability[] = [];
const initialIncomes: Income[] = [];
const initialExpenses: Expense[] = [];
const initialGoals: Goal[] = [{ id: 'initial-1', name: '', corpus: '', years: '', rate: 12, currentSave: '', currentSip: '' }];
const initialRetirementInputs: RetirementInputs = {
    currentAge: '',
    desiredRetirementAge: '',
    lifeExpectancy: '',
    currentMonthlyExpense: '',
    preRetirementRoi: '',
    postRetirementRoi: '',
    incrementalRate: '',
    currentSavings: '',
    currentSip: '',
};
const initialAssetAllocation: AssetAllocationProfile = { age: '', riskAppetite: '' };
const initialFundAllocations: FundAllocation[] = [];
const initialLifeQuotes: LifeInsuranceQuote[] = [];
const initialHealthQuotes: HealthInsuranceQuote[] = [];


const STORAGE_KEY = 'financial_planner_form_data';

export function Planner() {
  const { toast } = useToast();
  const router = useRouter();
  const { user } = useAuth();

  const [personalDetails, setPersonalDetails] = useState<PersonalDetails>(initialPersonalDetails);
  const [assets, setAssets] = useState<Asset[]>(initialAssets);
  const [liabilities, setLiabilities] = useState<Liability[]>(initialLiabilities);
  const [incomes, setIncomes] = useState<Income[]>(initialIncomes);
  const [expenses, setExpenses] = useState<Expense[]>(initialExpenses);
  const [goals, setGoals] = useState<Goal[]>(initialGoals);
  const [insuranceAnalysisData, setInsuranceAnalysisData] = useState<Pick<InsuranceAnalysisData, 'lifeInsurance' | 'healthInsurance'>>({ lifeInsurance: { recommendedCover: 0, currentCover: '', currentPremium: '', coverageGap: 0, quotes: [] }, healthInsurance: { recommendedCover: '', currentCover: '', currentPremium: '', coverageGap: 0, quotes: [] } });
  const [lifeQuotes, setLifeQuotes] = useState<LifeInsuranceQuote[]>(initialLifeQuotes);
  const [healthQuotes, setHealthQuotes] = useState<HealthInsuranceQuote[]>(initialHealthQuotes);
  const [willStatus, setWillStatus] = useState<'yes' | 'no' | null>(null);
  const [retirementInputs, setRetirementInputs] = useState<RetirementInputs>(initialRetirementInputs);
  const [assetAllocationProfile, setAssetAllocationProfile] = useState<AssetAllocationProfile>(initialAssetAllocation);
  const [fundAllocations, setFundAllocations] = useState<FundAllocation[]>(initialFundAllocations);

  const [optimizedGoals, setOptimizedGoals] = useState<SipOptimizerGoal[]>([]);

  const [isGenerating, setIsGenerating] = useState(false);
  const [isHydrated, setIsHydrated] = useState(false);

  useEffect(() => {
    try {
      const savedData = sessionStorage.getItem(STORAGE_KEY);
      if (savedData) {
        const parsed = JSON.parse(savedData);
        if (parsed.personalDetails) setPersonalDetails(parsed.personalDetails);
        if (parsed.assets) setAssets(parsed.assets);
        if (parsed.liabilities) setLiabilities(parsed.liabilities);
        if (parsed.incomes) setIncomes(parsed.incomes);
        if (parsed.expenses) setExpenses(parsed.expenses);
        if (parsed.goals) setGoals(parsed.goals);
        if (parsed.insuranceAnalysisData) setInsuranceAnalysisData(parsed.insuranceAnalysisData);
        if (parsed.lifeQuotes) setLifeQuotes(parsed.lifeQuotes);
        if (parsed.healthQuotes) setHealthQuotes(parsed.healthQuotes);
        if (parsed.willStatus !== undefined) setWillStatus(parsed.willStatus);
        if (parsed.retirementInputs) setRetirementInputs(parsed.retirementInputs);
        if (parsed.assetAllocationProfile) setAssetAllocationProfile(parsed.assetAllocationProfile);
        if (parsed.fundAllocations) setFundAllocations(parsed.fundAllocations);
      }
    } catch (error) {
      console.error('Error loading saved form data:', error);
    }
    setIsHydrated(true);
  }, []);

  useEffect(() => {
    if (!isHydrated) return;

    try {
      const dataToSave = {
        personalDetails,
        assets,
        liabilities,
        incomes,
        expenses,
        goals,
        insuranceAnalysisData,
        lifeQuotes,
        healthQuotes,
        willStatus,
        retirementInputs,
        assetAllocationProfile,
        fundAllocations,
      };
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(dataToSave));
    } catch (error) {
      console.error('Error saving form data:', error);
    }
  }, [
    isHydrated,
    personalDetails,
    assets,
    liabilities,
    incomes,
    expenses,
    goals,
    insuranceAnalysisData,
    lifeQuotes,
    healthQuotes,
    willStatus,
    retirementInputs,
    assetAllocationProfile,
    fundAllocations,
  ]);

  const getNumericValue = (val: number | '') => typeof val === 'number' ? val : 0;

  const age = useMemo(() => calculateAge(personalDetails.dob), [personalDetails.dob]);

  useEffect(() => {
    if (age !== null) {
      setAssetAllocationProfile(prev => ({ ...prev, age: age }));
      setRetirementInputs(prev => ({ ...prev, currentAge: age }));
    }
  }, [age]);

  useEffect(() => {
    if (personalDetails.retirementAge) {
      setRetirementInputs(prev => ({...prev, desiredRetirementAge: personalDetails.retirementAge}));
    }
  }, [personalDetails.retirementAge]);

  const totalAssets = useMemo(() => assets.reduce((sum, a) => sum + getNumericValue(a.amount), 0), [assets]);
  const totalLiabilities = useMemo(() => liabilities.reduce((sum, l) => sum + getNumericValue(l.amount), 0), [liabilities]);
  const netWorth = useMemo(() => totalAssets - totalLiabilities, [totalAssets, totalLiabilities]);

  const totalMonthlyIncome = useMemo(() => incomes.reduce((sum, i) => sum + getNumericValue(i.amount), 0), [incomes]);
  const totalMonthlyExpenses = useMemo(() => expenses.reduce((sum, e) => sum + getNumericValue(e.amount), 0), [expenses]);
  const monthlyCashflow = useMemo(() => totalMonthlyIncome - totalMonthlyExpenses, [totalMonthlyIncome, totalMonthlyExpenses]);
  const yearlyCashflow = useMemo(() => monthlyCashflow * 12, [monthlyCashflow]);

  const investibleSurplus = useMemo(() => monthlyCashflow > 0 ? monthlyCashflow : 0, [monthlyCashflow]);

  const goalsWithCalculations = useMemo<GoalWithCalculations[]>(() => goals.map(g => calculateGoalDetails(g)), [goals]);
  const retirementCalculations = useMemo<RetirementCalculations>(() => calculateRetirementDetails(retirementInputs), [retirementInputs]);

  const insuranceAnalysis: InsuranceAnalysisData = useMemo(() => ({
    ...insuranceAnalysisData,
    lifeInsurance: { ...insuranceAnalysisData.lifeInsurance, quotes: lifeQuotes },
    healthInsurance: { ...insuranceAnalysisData.healthInsurance, quotes: healthQuotes }
  }), [insuranceAnalysisData, lifeQuotes, healthQuotes]);

  const allPlannerData: AllPlannerData = useMemo(() => ({
    personalDetails,
    assets,
    liabilities,
    incomes,
    expenses,
    goals,
    insuranceAnalysis,
    willStatus,
    retirementInputs,
    assetAllocationProfile,
    fundAllocations,
  }), [
    personalDetails, assets, liabilities, incomes, expenses, goals, insuranceAnalysis,
    willStatus, retirementInputs, assetAllocationProfile, fundAllocations
  ]);

  useEffect(() => {
    const calculateOptimizedGoals = async () => {
      try {
        const response = await fetch('/api/calculate-optimized-goals', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            goalsWithCalculations,
            investibleSurplus,
          }),
        });

        if (!response.ok) {
          throw new Error('Failed to calculate optimized goals');
        }

        const data = await response.json();
        setOptimizedGoals(data.optimizedGoals);
      } catch (error) {
        console.error('Error calculating optimized goals:', error);
      }
    };

    if (goalsWithCalculations.length > 0) {
      calculateOptimizedGoals();
    }
  }, [goalsWithCalculations, investibleSurplus]);

  const handleClearForm = () => {
    if(window.confirm("Are you sure you want to clear all data?")) {
        setPersonalDetails(initialPersonalDetails);
        setAssets(initialAssets);
        setLiabilities(initialLiabilities);
        setIncomes(initialIncomes);
        setExpenses(initialExpenses);
        setGoals(initialGoals);
        setWillStatus(null);
        setRetirementInputs(initialRetirementInputs);
        setAssetAllocationProfile(initialAssetAllocation);
        setFundAllocations(initialFundAllocations);
        setLifeQuotes(initialLifeQuotes);
        setHealthQuotes(initialHealthQuotes);
        sessionStorage.removeItem(STORAGE_KEY);
        toast({
            title: "Form Cleared",
            description: "All data has been reset.",
        });
    }
  };

  const handleDownloadCsv = () => {
    const dataForCsv = { ...allPlannerData, netWorth, yearlyCashflow };
    generateCsv(dataForCsv);
  };

  const handleGenerateReport = async () => {
    console.log('[Generate Report] Starting with personalDetails:', JSON.stringify(personalDetails));

    if (!personalDetails.name || !personalDetails.email) {
      toast({
        title: "Missing Information",
        description: "Please enter at least your name and email before generating a report.",
        variant: "destructive",
      });
      return;
    }
     const nonRetirementGoals = goals.filter(g => g.name.toLowerCase() !== 'retirement');
     if (nonRetirementGoals.length === 0 || nonRetirementGoals.every(g => !g.name)) {
      toast({
        title: "No Goals",
        description: "Please add at least one financial goal (other than retirement).",
        variant: "destructive"
      });
      return;
    }
    if (!insuranceAnalysis) {
      toast({
        title: "Insurance Data Missing",
        description: "Could not retrieve insurance analysis data. Please fill out the insurance section.",
        variant: "destructive"
      });
      return;
    }

    setIsGenerating(true);

    try {
      // Prepare data with user-specified "Other" values
      const processedAssets: Asset[] = assets.map(a => ({ ...a, type: a.type === 'Other' && a.otherType ? a.otherType : a.type }));
      const processedLiabilities: Liability[] = liabilities.map(l => ({ ...l, type: l.type === 'Other' && l.otherType ? l.otherType : l.type }));
      const processedExpenses: Expense[] = expenses.map(e => ({ ...e, type: e.type === 'Other' && e.otherType ? e.otherType : e.type, amount: getNumericValue(e.amount) * 12 }));

      const processedGoals: Goal[] = goals.map(g => ({ ...g, name: g.name === 'Other' && g.otherType ? g.otherType : g.name }));
      const processedGoalsWithCalculations: GoalWithCalculations[] = goalsWithCalculations.map((g, i) => ({ 
        ...g, 
        name: processedGoals[i].name 
      }));


      // Common data preparation
      let investibleSurplus = monthlyCashflow > 0 ? monthlyCashflow : 0;

      const findAssetAmount = (type: string) => {
        const asset = processedAssets.find(a => a.type === type);
        return asset ? getNumericValue(asset.amount) : 0;
      };
      const assetAllocation = {
          equity: { corpus: findAssetAmount('Indian Equity shares'), monthly: processedGoals.reduce((sum, g) => sum + getNumericValue(g.currentSip), 0) },
          fixedIncome: { corpus: findAssetAmount('Fixed Income instruments'), monthly: 0},
          ppf: { corpus: findAssetAmount('PPF'), monthly: 0},
          epf: { corpus: findAssetAmount('EPF'), monthly: 0},
          nps: { corpus: findAssetAmount('NPS'), monthly: 0},
          gold: { corpus: findAssetAmount('Gold/Gold Bond/ETF/Fund'), monthly: 0},
          insurance: { corpus: findAssetAmount('Insurance'), monthly: 0},
          realEstate: { corpus: findAssetAmount('Real Estate'), monthly: 0},
          others: { corpus: findAssetAmount('Other'), monthly: 0 }, // Note: This might need adjustment if multiple 'Other' assets exist
          total: { corpus: 0, monthly: 0 }
      };

      assetAllocation.total.corpus = Object.values(assetAllocation).reduce((sum, val) => sum + (val.corpus || 0), 0) - assetAllocation.total.corpus;
      assetAllocation.total.monthly = Object.values(assetAllocation).reduce((sum, val) => sum + (val.monthly || 0), 0) - assetAllocation.total.monthly;

      // New Retirement Goal Logic
      let retirementGoalReport: RetirementGoalReport | null = null;
      const retirementRequiredSip = retirementCalculations.monthlyInvestmentNeeded;

      if (retirementRequiredSip > 0) {
          const currentRetirementSip = getNumericValue(retirementInputs.currentSip);
          let allocatedRetirementSip = 0;

          if (investibleSurplus >= retirementRequiredSip) {
              allocatedRetirementSip = retirementRequiredSip;
              investibleSurplus -= retirementRequiredSip;
          } else {
              allocatedRetirementSip = investibleSurplus;
              investibleSurplus = 0;
          }

          const potentialRetirementCorpus = calculateFutureValue(
              allocatedRetirementSip,
              getNumericValue(retirementInputs.preRetirementRoi),
              retirementCalculations.yearsToRetirement,
              getNumericValue(retirementInputs.currentSavings)
          );

          const targetCorpusForTimeline = retirementCalculations.requiredRetirementCorpus;
          const preRetirementRoiForTimeline = getNumericValue(retirementInputs.preRetirementRoi);

          const totalCurrentRetirementAssets = getNumericValue(retirementInputs.currentSavings) + calculateFutureValue(getNumericValue(retirementInputs.currentSip), getNumericValue(retirementInputs.preRetirementRoi), retirementCalculations.yearsToRetirement, 0);

          let potentialTimeline;
          if (allocatedRetirementSip >= retirementRequiredSip) {
              potentialTimeline = retirementCalculations.yearsToRetirement;
          } else {
              potentialTimeline = calculateNper(
                  targetCorpusForTimeline,
                  preRetirementRoiForTimeline,
                  allocatedRetirementSip,
                  getNumericValue(retirementInputs.currentSavings) + calculateFutureValue(0, preRetirementRoiForTimeline, retirementCalculations.yearsToRetirement, getNumericValue(retirementInputs.currentSip)) // This seems off
              );
          }

          const currentTimeline = calculateNper(
              targetCorpusForTimeline,
              preRetirementRoiForTimeline,
              currentRetirementSip,
              getNumericValue(retirementInputs.currentSavings)
          );


          retirementGoalReport = {
              futureValue: retirementCalculations.requiredRetirementCorpus,
              timeline: {
                current: currentTimeline,
                required: retirementCalculations.yearsToRetirement,
                potential: potentialTimeline,
              },
              investmentStatus: {
                  currentInvestment: currentRetirementSip,
                  requiredInvestment: retirementRequiredSip,
                  allocatedInvestment: allocatedRetirementSip,
              },
              potentialCorpus: potentialRetirementCorpus,
          };
      }


      // SIP Optimizer Logic for other goals
      const otherGoalsCalculations = processedGoalsWithCalculations.filter(g => g.name.toLowerCase() !== 'retirement');
      const totalRequiredSipForOtherGoals = otherGoalsCalculations.reduce((sum, goal) => sum + goal.newSipRequired, 0);
      let surplusForWealthCreation = 0;
      let optimizerGoals: SipOptimizerGoal[] = [];

      if (investibleSurplus >= totalRequiredSipForOtherGoals) {
        // CASE 1 & 3: All goals are covered, potentially with surplus
        surplusForWealthCreation = investibleSurplus - totalRequiredSipForOtherGoals;
        optimizerGoals = otherGoalsCalculations.map(goal => {
            const potentialCorpus = calculateFutureValue(goal.newSipRequired, getNumericValue(goal.rate), getNumericValue(goal.years), getNumericValue(goal.currentSave));
            const potentialCorpusWithCurrentSip = calculateFutureValue(getNumericValue(goal.currentSip), getNumericValue(goal.rate), getNumericValue(goal.years), getNumericValue(goal.currentSave));

            return {
                id: goal.id,
                name: goal.name,
                targetCorpus: getNumericValue(goal.corpus),
                futureValue: potentialCorpus,
                timeline: {
                    current: getNumericValue(goal.years),
                    required: getNumericValue(goal.years),
                    potential: getNumericValue(goal.years),
                },
                investmentStatus: {
                    currentInvestment: getNumericValue(goal.currentSip),
                    requiredInvestment: goal.newSipRequired,
                    allocatedInvestment: goal.newSipRequired, // Fund exactly what's required
                },
                potentialCorpus: potentialCorpusWithCurrentSip,
            };
        });
      } else {
        // CASE 2: SIPs exceed cashflow, allocate proportionally based on required SIP ratio
        optimizerGoals = otherGoalsCalculations.map(goal => {
            let allocatedInvestment = 0;
            if (otherGoalsCalculations.length === 1) {
                allocatedInvestment = investibleSurplus;
            } else if (totalRequiredSipForOtherGoals > 0) {
                const weight = goal.newSipRequired / totalRequiredSipForOtherGoals;
                allocatedInvestment = investibleSurplus * weight;
            }

            const potentialCorpus = calculateFutureValue(allocatedInvestment, getNumericValue(goal.rate), getNumericValue(goal.years), getNumericValue(goal.currentSave));
            const potentialCorpusWithCurrentSip = calculateFutureValue(getNumericValue(goal.currentSip), getNumericValue(goal.rate), getNumericValue(goal.years), getNumericValue(goal.currentSave));

            return {
                id: goal.id,
                name: goal.name,
                targetCorpus: getNumericValue(goal.corpus),
                futureValue: potentialCorpus,
                timeline: {
                    current: getNumericValue(goal.years),
                    required: getNumericValue(goal.years),
                    potential: getNumericValue(goal.years),
                },
                investmentStatus: {
                    currentInvestment: getNumericValue(goal.currentSip),
                    requiredInvestment: goal.newSipRequired,
                    allocatedInvestment: allocatedInvestment,
                },
                potentialCorpus: potentialCorpusWithCurrentSip,
            };
        });
      }

      let wealthCreationGoal: WealthCreationGoal | null = null;
      if (surplusForWealthCreation > 0) {
          const defaultRate = processedGoals.length > 0 ? (processedGoals.reduce((acc, g) => acc + getNumericValue(g.rate), 0) / processedGoals.length) : 12;
          wealthCreationGoal = calculateWealthCreation(surplusForWealthCreation, defaultRate);
      }

      const totalCurrentInvestment = optimizerGoals.reduce((sum, g) => sum + g.investmentStatus.currentInvestment, 0) + getNumericValue(retirementInputs.currentSip);
      const totalRequiredInvestment = totalRequiredSipForOtherGoals + (retirementGoalReport?.investmentStatus.requiredInvestment || 0);
      const totalPotentialInvestment = (monthlyCashflow > 0 ? monthlyCashflow : 0);

       const totalInvestmentStatus = {
          currentInvestment: totalCurrentInvestment,
          requiredInvestment: totalRequiredInvestment,
          potentialInvestment: totalPotentialInvestment,
      };

       // SIP Optimizer Report Data
      console.log('[Generate Report] Creating SIP report with personalDetails:', {
        name: personalDetails.name,
        dob: personalDetails.dob,
        mobile: personalDetails.mobile,
        email: personalDetails.email
      });

      const generatedSipReportData: SipOptimizerReportData & { goalsWithCalculations: GoalWithCalculations[] } = {
          personalDetails: {
              name: personalDetails.name || "N/A",
              dob: personalDetails.dob || "N/A",
              dependents: getNumericValue(personalDetails.dependents),
              retirementAge: getNumericValue(personalDetails.retirementAge),
              mobile: personalDetails.mobile || "N/A",
              email: personalDetails.email || "N/A",
              arn: personalDetails.arn || "N/A",
          },
          netWorth: netWorth,
          cashflow: {
              totalMonthlyIncome: totalMonthlyIncome,
              totalMonthlyExpenses: totalMonthlyExpenses,
              investibleSurplus: (monthlyCashflow > 0 ? monthlyCashflow : 0),
          },
          goals: optimizerGoals,
          retirementGoal: retirementGoalReport,
          wealthCreationGoal: wealthCreationGoal,
          totalInvestmentStatus,
          detailedTables: {
              incomeExpenses: {
                  totalMonthlyIncome: totalMonthlyIncome,
                  fixedExpenses: processedExpenses.filter(e => e.type === 'Rent').reduce((sum, e) => sum + getNumericValue(e.amount), 0) / 12,
                  emiExpenses: 0, // Placeholder
                  otherExpenses: processedExpenses.filter(e => e.type !== 'Rent').reduce((sum, e) => sum + getNumericValue(e.amount), 0) / 12,
              },
              assetAllocation: assetAllocation
          },
          advisorDetails: {
            arnName: 'Gunjan Kataria',
            arnNo: personalDetails.arn || 'ARN-157982',
            mobile: '9460825477',
            email: 'contact@financialfriend.in',
          },
          insuranceAnalysis: insuranceAnalysis,
          assets: processedAssets,
          willStatus: willStatus,
          retirementInputs: retirementInputs,
          retirementCalculations: retirementCalculations,
          assetAllocationProfile: assetAllocationProfile,
          fundAllocations: fundAllocations,
          goalsWithCalculations: processedGoalsWithCalculations,
      };

      // Detailed Wellness Report Data
      const goalsWithSip: GoalWithSip[] = processedGoals.map(g => ({
        ...g,
        sip: calculateSip(g)
      }));

       const summaryInput = {
        name: personalDetails.name || "User",
        netWorth,
        monthlyCashflow,
        insuranceCover: getNumericValue(insuranceAnalysis.lifeInsurance.currentCover as number | '') + getNumericValue(insuranceAnalysis.healthInsurance.currentCover as number | ''),
        insurancePremium: getNumericValue(insuranceAnalysis.lifeInsurance.currentPremium as number | '') + getNumericValue(insuranceAnalysis.healthInsurance.currentPremium as number | ''),
        goals: goalsWithSip.map(g => ({
          goalName: g.name,
          corpus: getNumericValue(g.corpus),
          years: getNumericValue(g.years),
          rate: getNumericValue(g.rate),
          sip: g.sip
        })),
      };

      const summaryResponse = await fetch('/api/summarize-financial-status', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(summaryInput),
      });
      const { summary } = await summaryResponse.json();

      const generatedDetailedReportData: ReportData = {
        personalDetails: personalDetails,
        netWorth: netWorth,
        monthlyCashflow: monthlyCashflow,
        totalInsuranceCover: 0,
        totalInsurancePremium: 0,
        goals: goalsWithSip,
        totalAssets: totalAssets,
        totalLiabilities: totalLiabilities,
        assets: processedAssets,
        liabilities: processedLiabilities,
        totalAnnualIncome: totalMonthlyIncome * 12,
        totalAnnualExpenses: totalMonthlyExpenses * 12,
        expenses: processedExpenses,
        aiSummary: summary,
        willStatus: willStatus,
      };

      // Generate unique report ID using timestamp and user ID
      const reportId = `${user?.uid || 'guest'}_${Date.now()}`;

      // Store data in Replit Database via API for persistence
      try {
        const storeResponse = await fetch('/api/store-report', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            reportId,
            userId: user?.uid || 'guest',
            detailedReport: generatedDetailedReportData,
            sipReport: generatedSipReportData,
          }),
        });

        if (!storeResponse.ok) {
          console.error('Failed to store report data');
        }
      } catch (storeError) {
        console.error('Error storing report:', storeError);
      }

      // Navigate to report with report ID in URL
      router.push(`/sip-optimizer-report?id=${reportId}`);

    } catch (error) {
      console.error("Error generating report:", error);
      toast({
        title: "Error",
        description: "Failed to generate report. Please check the console for details.",
        variant: "destructive",
      });
    } finally {
      setIsGenerating(false);
    }
  };

  if (!user) {
    return (
      <div className="flex h-screen items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="bg-background">
      <header className="z-40 w-full border-b bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/60">
        <AppHeader />
      </header>
      <div className="container mx-auto p-4 md:p-8">
        <div className="text-center mb-12">
            <h2 className="text-3xl md:text-4xl font-bold font-headline text-foreground">Plan Your Financial Future</h2>
            <p className="text-muted-foreground mt-2 max-w-2xl mx-auto">Fill in the details below to get a comprehensive overview of your financial health and a personalized plan to achieve your goals.</p>
        </div>

        <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 items-start">
          <PersonalDetailsForm details={personalDetails} setDetails={setPersonalDetails} />
          <AssetsLiabilitiesForm 
            assets={assets} 
            setAssets={setAssets} 
            liabilities={liabilities} 
            setLiabilities={setLiabilities}
            netWorth={netWorth}
          />
          <IncomeExpensesForm
            incomes={incomes}
            setIncomes={setIncomes}
            expenses={expenses}
            setExpenses={setExpenses}
            monthlyCashflow={monthlyCashflow}
            yearlyCashflow={yearlyCashflow}
          />
          <InsuranceForm
            age={age}
            incomes={incomes}
            onInsuranceDataChange={setInsuranceAnalysisData}
          />
          <GoalsForm
            goals={goals}
            setGoals={setGoals}
            goalsWithCalculations={goalsWithCalculations}
          />
           <RetirementPlannerForm
            inputs={retirementInputs}
            setInputs={setRetirementInputs}
            calculations={retirementCalculations}
          />
           <EstatePlanningForm
            willStatus={willStatus}
            setWillStatus={setWillStatus}
          />
          <AssetAllocationForm
            age={age}
            profile={assetAllocationProfile}
            setProfile={setAssetAllocationProfile}
          />
          <RecommendedFunds
            allocations={fundAllocations}
            setAllocations={setFundAllocations}
            investibleSurplus={investibleSurplus}
            optimizedGoals={optimizedGoals}
            goals={goals}
            retirementCalculations={retirementCalculations}
           />
          <InsuranceQuotesForm
             lifeQuotes={lifeQuotes}
             setLifeQuotes={setLifeQuotes}
             healthQuotes={healthQuotes}
             setHealthQuotes={setHealthQuotes}
          />

        </div>

        <div className="mt-12 text-center flex justify-center items-center gap-4">
          <Button onClick={handleGenerateReport} disabled={isGenerating} size="lg" className="shadow-lg hover:shadow-xl transition-shadow">
            {isGenerating ? (
              <>
                <Loader2 className="mr-2 h-5 w-5 animate-spin" /> Generating Reports...
              </>
            ) : "Generate Financial Reports"}
          </Button>
           <Button onClick={handleDownloadCsv} variant="outline" size="lg" className="shadow-lg hover:shadow-xl transition-shadow">
              <Download className="mr-2 h-5 w-5" /> Download as CSV
          </Button>
          <Button onClick={handleClearForm} variant="destructive" size="lg" className="shadow-lg hover:shadow-xl transition-shadow">
              <Eraser className="mr-2 h-5 w-5" /> Clear Form
          </Button>
        </div>

      </div>
       <footer className="text-center p-4 text-muted-foreground text-sm border-t mt-12">
        &copy; {new Date().getFullYear()} FinFriend Planner. All rights reserved.
      </footer>
    </div>
  );
}

src/components/planner/FundAllocationIte.content:
"use client";

import { useMemo, useState, useEffect } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Trash2, Loader2, AlertCircle, PieChart, BarChart3, TrendingUp } from 'lucide-react';
import type { FundAllocation, Goal, FundReturnsOutput, SipOptimizerGoal, RetirementCalculations, FactsheetData } from '@/lib/types';
import { loadMutualFundsFromCSV, MutualFundScheme, fetchNAV, NAVData } from '@/lib/load-funds';
import { getFundReturns } from '@/ai/flows/fund-returns-flow';
import { analyzeFactsheet } from '@/ai/flows/analyze-factsheet-flow';
import { useToast } from '@/hooks/use-toast';
import { SearchableSelect } from '@/components/ui/searchable-select';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, ReferenceLine } from 'recharts';

interface YearlyComparison {
  year: string;
  fundReturn: number;
  benchmarkReturn: number;
}

interface FundAllocationItemProps {
  alloc: FundAllocation;
  availableGoals: Goal[];
  onUpdate: (id: string, field: string, value: string | number) => void;
  onRemove: (id: string) => void;
  optimizedGoals: SipOptimizerGoal[];
  allocatedSipForGoal: number;
  retirementCalculations: RetirementCalculations;
}

export function FundAllocationItem({
  alloc,
  availableGoals,
  onUpdate,
  onRemove,
  optimizedGoals,
  allocatedSipForGoal,
  retirementCalculations,
}: FundAllocationItemProps) {
  const { toast } = useToast();
  const [allFunds, setAllFunds] = useState<MutualFundScheme[]>([]);
  const [isLoadingFunds, setIsLoadingFunds] = useState(true);
  const [returns, setReturns] = useState<FundReturnsOutput | null>(null);
  const [isLoadingReturns, setIsLoadingReturns] = useState(false);
  const [navData, setNavData] = useState<NAVData | null>(null);
  const [isFetchingNAV, setIsFetchingNAV] = useState(false);
  const [navError, setNavError] = useState<string | null>(null);
  const [factsheetManifest, setFactsheetManifest] = useState<Record<string, Record<string, string>>>({});
  const [factsheetData, setFactsheetData] = useState<FactsheetData | null>(null);
  const [isLoadingFactsheet, setIsLoadingFactsheet] = useState(false);
  const [factsheetError, setFactsheetError] = useState<string | null>(null);
  const [benchmarkComparison, setBenchmarkComparison] = useState<YearlyComparison[]>([]);
  const [benchmarkName, setBenchmarkName] = useState<string>('');
  const [isLoadingBenchmark, setIsLoadingBenchmark] = useState(false);

  useEffect(() => {
    const loadData = async () => {
      try {
        const funds = await loadMutualFundsFromCSV();
        setAllFunds(funds);
      } catch (error) {
        console.error('Error loading funds:', error);
        toast({
          title: 'Error Loading Funds',
          description: 'Could not load mutual funds data from CSV',
          variant: 'destructive',
        });
      } finally {
        setIsLoadingFunds(false);
      }
    };
    loadData();
  }, [toast]);

  useEffect(() => {
    fetch('/factsheets.json')
      .then(res => res.json())
      .then(data => setFactsheetManifest(data))
      .catch(err => console.error("Could not load factsheets.json", err));
  }, []);

  useEffect(() => {
    const analyzeFactsheetForFund = async () => {
      if (!alloc.fundName || !alloc.schemeName || Object.keys(factsheetManifest).length === 0) {
        setFactsheetData(null);
        setFactsheetError(null);
        return;
      }

      const fundHouseSchemes = factsheetManifest[alloc.fundName];
      if (!fundHouseSchemes) {
        setFactsheetData(null);
        setFactsheetError(null);
        return;
      }

      const matchingKey = Object.keys(fundHouseSchemes).find(key =>
        alloc.schemeName.toLowerCase().startsWith(key.toLowerCase())
      );

      if (!matchingKey || !fundHouseSchemes[matchingKey]) {
        setFactsheetData(null);
        setFactsheetError(null);
        return;
      }

      setIsLoadingFactsheet(true);
      setFactsheetError(null);

      try {
        console.log(`[Factsheet] Analyzing factsheet for ${alloc.fundName}: ${fundHouseSchemes[matchingKey]}`);
        const data = await analyzeFactsheet(fundHouseSchemes[matchingKey]);
        setFactsheetData(data);
        console.log(`[Factsheet] Successfully analyzed factsheet for ${alloc.fundName}`);
      } catch (error: any) {
        console.error(`[Factsheet] Failed to analyze factsheet for ${alloc.fundName}:`, error);
        setFactsheetError(error.message || 'Failed to analyze factsheet');
        setFactsheetData(null);
      } finally {
        setIsLoadingFactsheet(false);
      }
    };

    const timeoutId = setTimeout(analyzeFactsheetForFund, 1000);
    return () => clearTimeout(timeoutId);
  }, [alloc.fundName, alloc.schemeName, factsheetManifest]);

  const categories = useMemo(() => {
    const cats = new Set(allFunds.map(f => f.category));
    return Array.from(cats).sort();
  }, [allFunds]);

  const types = useMemo(() => {
    if (!alloc.fundCategory) return [];
    const filtered = allFunds.filter(f => f.category === alloc.fundCategory);
    const typeSet = new Set(filtered.map(f => f.type));
    return Array.from(typeSet).sort();
  }, [alloc.fundCategory, allFunds]);

  const mutualFunds = useMemo(() => {
    if (!alloc.fundCategory || !alloc.fundType) return [];
    const filtered = allFunds.filter(
      f => f.category === alloc.fundCategory && f.type === alloc.fundType
    );
    const fundSet = new Set(filtered.map(f => f.fundName));
    return Array.from(fundSet).sort();
  }, [alloc.fundCategory, alloc.fundType, allFunds]);

  const schemes = useMemo(() => {
    if (!alloc.fundCategory || !alloc.fundType || !alloc.fundName) return [];
    const filtered = allFunds.filter(
      f => f.category === alloc.fundCategory && 
           f.type === alloc.fundType && 
           f.fundName === alloc.fundName
    );
    return filtered.sort((a, b) => a.schemeName.localeCompare(b.schemeName));
  }, [alloc.fundCategory, alloc.fundType, alloc.fundName, allFunds]);

  const remainingSip = useMemo(() => {
    if (alloc.goalId === 'retirement') {
      return retirementCalculations.monthlyInvestmentNeeded;
    }
    const selectedGoal = optimizedGoals.find(g => g.id === alloc.goalId);
    if (!selectedGoal) return 0;
    const goalAllocatedSip = selectedGoal.investmentStatus.allocatedInvestment;
    const currentSipForThisAlloc = typeof alloc.sipRequired === 'number' ? alloc.sipRequired : 0;
    return goalAllocatedSip - allocatedSipForGoal + currentSipForThisAlloc;
  }, [alloc.goalId, alloc.sipRequired, optimizedGoals, allocatedSipForGoal, retirementCalculations]);

  useEffect(() => {
    const fetchSchemeNAV = async () => {
      if (!alloc.schemeCode || alloc.schemeCode.length === 0) {
        setNavData(null);
        setNavError(null);
        return;
      }

      setIsFetchingNAV(true);
      setNavError(null);

      try {
        const nav = await fetchNAV(alloc.schemeCode);
        if (nav) {
          setNavData(nav);
        } else {
          setNavError('NAV data currently unavailable. Please try again later.');
        }
      } catch (error) {
        setNavError('NAV data currently unavailable. Please try again later.');
      } finally {
        setIsFetchingNAV(false);
      }
    };

    const timeoutId = setTimeout(fetchSchemeNAV, 300);
    return () => clearTimeout(timeoutId);
  }, [alloc.schemeCode]);

  useEffect(() => {
    const fetchReturns = async () => {
      if (alloc.schemeCode && alloc.schemeCode.length > 0) {
        setIsLoadingReturns(true);
        setReturns(null);
        try {
          const schemeCodeNum = Number(alloc.schemeCode);
          console.log(`[CAGR Debug] Fetching returns for scheme code: ${schemeCodeNum} (${alloc.schemeName})`);
          const result = await getFundReturns({ schemeCode: schemeCodeNum });
          console.log(`[CAGR Debug] Received CAGR data:`, result);
          setReturns(result);
        } catch (error) {
          console.error('[CAGR Debug] Failed to fetch fund returns:', error);
          setReturns(null);
        } finally {
          setIsLoadingReturns(false);
        }
      } else {
        console.log('[CAGR Debug] No scheme code available');
        setReturns(null);
      }
    };

    const timeoutId = setTimeout(fetchReturns, 500);
    return () => clearTimeout(timeoutId);
  }, [alloc.schemeCode, alloc.schemeName]);

  useEffect(() => {
    const fetchBenchmarkComparison = async () => {
      if (!alloc.schemeCode || !alloc.schemeName) {
        setBenchmarkComparison([]);
        setBenchmarkName('');
        return;
      }

      setIsLoadingBenchmark(true);
      try {
        const response = await fetch('/api/fund-benchmark-comparison', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            schemeCode: Number(alloc.schemeCode),
            schemeName: alloc.schemeName,
            fundCategory: alloc.fundCategory
          })
        });

        if (response.ok) {
          const data = await response.json();
          setBenchmarkComparison(data.yearlyComparison || []);
          setBenchmarkName(data.benchmarkName || 'Benchmark');
        } else {
          setBenchmarkComparison([]);
        }
      } catch (error) {
        console.error('Failed to fetch benchmark comparison:', error);
        setBenchmarkComparison([]);
      } finally {
        setIsLoadingBenchmark(false);
      }
    };

    const timeoutId = setTimeout(fetchBenchmarkComparison, 800);
    return () => clearTimeout(timeoutId);
  }, [alloc.schemeCode, alloc.schemeName, alloc.fundCategory]);

  const handleCategoryChange = (value: string) => {
    onUpdate(alloc.id, 'fundCategory', value);
    onUpdate(alloc.id, 'fundType', '');
    onUpdate(alloc.id, 'fundName', '');
    onUpdate(alloc.id, 'schemeName', '');
    onUpdate(alloc.id, 'schemeCode', '');
    setNavData(null);
    setNavError(null);
    setFactsheetData(null);
    setFactsheetError(null);
  };

  const handleTypeChange = (value: string) => {
    onUpdate(alloc.id, 'fundType', value);
    onUpdate(alloc.id, 'fundName', '');
    onUpdate(alloc.id, 'schemeName', '');
    onUpdate(alloc.id, 'schemeCode', '');
    setNavData(null);
    setNavError(null);
    setFactsheetData(null);
    setFactsheetError(null);
  };

  const handleMutualFundChange = (value: string) => {
    onUpdate(alloc.id, 'fundName', value);
    onUpdate(alloc.id, 'schemeName', '');
    onUpdate(alloc.id, 'schemeCode', '');
    setNavData(null);
    setNavError(null);
    setFactsheetData(null);
    setFactsheetError(null);
  };

  const handleSchemeChange = (value: string) => {
    onUpdate(alloc.id, 'schemeName', value);

    const selectedScheme = schemes.find(s => s.schemeName === value);
    if (selectedScheme && selectedScheme.schemeCode) {
      onUpdate(alloc.id, 'schemeCode', selectedScheme.schemeCode);
      console.log(`[Scheme Code] Using code ${selectedScheme.schemeCode} from CSV for scheme: ${value}`);
    } else {
      onUpdate(alloc.id, 'schemeCode', '');
      console.log(`[Scheme Code] No code found in CSV for scheme: ${value}`);
    }
  };

  if (isLoadingFunds) {
    return (
      <Card className="p-4">
        <div className="flex items-center justify-center py-8">
          <Loader2 className="h-5 w-5 animate-spin mr-2" />
          <span>Loading fund data...</span>
        </div>
      </Card>
    );
  }

  return (
    <Card key={alloc.id} className="p-4 relative">
      <Button
        variant="ghost"
        size="icon"
        className="absolute top-2 right-2 h-7 w-7 text-destructive"
        onClick={() => onRemove(alloc.id)}
      >
        <Trash2 className="h-4 w-4" />
      </Button>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 items-end mb-4">
        <div className="space-y-1.5">
          <Label htmlFor={`goalId-${alloc.id}`}>Goal Name</Label>
          <Select
            value={alloc.goalId}
            onValueChange={(value) => onUpdate(alloc.id, 'goalId', value)}
          >
            <SelectTrigger id={`goalId-${alloc.id}`}>
              <SelectValue placeholder="Select a goal" />
            </SelectTrigger>
            <SelectContent>
              {availableGoals.map(goal => (
                <SelectItem key={goal.id} value={goal.id}>
                  {goal.otherType || goal.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-1.5">
          <Label className="text-green-700 dark:text-green-400">
            Allocated SIP (remaining for this goal)
          </Label>
          <Input
            type="text"
            readOnly
            value={`₹${remainingSip.toLocaleString('en-IN')}`}
            className="bg-slate-100 dark:bg-slate-800"
          />
        </div>

        <div className="space-y-1.5">
          <Label htmlFor={`sipRequired-${alloc.id}`}>SIP required for fund</Label>
          <Input
            id={`sipRequired-${alloc.id}`}
            type="number"
            placeholder="e.g., 5000"
            value={typeof alloc.sipRequired === 'number' ? alloc.sipRequired : ''}
            onChange={(e) => onUpdate(alloc.id, 'sipRequired', e.target.value ? parseInt(e.target.value) : '')}
          />
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="space-y-1.5">
          <Label htmlFor={`category-${alloc.id}`}>Category</Label>
          <SearchableSelect
            options={categories}
            value={alloc.fundCategory}
            onChange={handleCategoryChange}
            placeholder="Select category"
          />
        </div>

        <div className="space-y-1.5">
          <Label htmlFor={`type-${alloc.id}`}>Type</Label>
          <SearchableSelect
            options={types}
            value={alloc.fundType || ''}
            onChange={handleTypeChange}
            placeholder={alloc.fundCategory ? "Select type" : "Select category first"}
            disabled={!alloc.fundCategory}
          />
        </div>

        <div className="space-y-1.5">
          <Label htmlFor={`mutualFund-${alloc.id}`}>Mutual Fund</Label>
          <SearchableSelect
            options={mutualFunds}
            value={alloc.fundName}
            onChange={handleMutualFundChange}
            placeholder={alloc.fundType ? "Select mutual fund" : "Select type first"}
            disabled={!alloc.fundType}
          />
        </div>

        <div className="space-y-1.5">
          <Label htmlFor={`scheme-${alloc.id}`}>Scheme Name</Label>
          <SearchableSelect
            options={schemes.map(s => s.schemeName)}
            value={alloc.schemeName}
            onChange={handleSchemeChange}
            placeholder={alloc.fundName ? "Select scheme" : "Select mutual fund first"}
            disabled={!alloc.fundName}
          />
        </div>
      </div>

      {isFetchingNAV && (
        <div className="mt-4 flex items-center text-sm text-muted-foreground">
          <Loader2 className="h-4 w-4 animate-spin mr-2" />
          Fetching NAV...
        </div>
      )}

      {navError && (
        <Alert variant="destructive" className="mt-4">
          <AlertCircle className="h-4 w-4" />
          <AlertDescription>{navError}</AlertDescription>
        </Alert>
      )}

      {navData && !isFetchingNAV && (
        <div className="mt-4 bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 rounded-lg p-4">
          <div className="flex justify-between items-center">
            <div>
              <p className="text-sm text-muted-foreground">Current NAV</p>
              <p className="text-2xl font-bold text-green-600 dark:text-green-400">₹{navData.nav}</p>
            </div>
            <div className="text-right">
              <p className="text-sm text-muted-foreground">As of</p>
              <p className="font-medium">{navData.date}</p>
            </div>
          </div>
        </div>
      )}

      {isLoadingReturns && (
