"use client";

import type { SipOptimizerGoal } from '@/lib/types';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';

interface Props {
  optimizedGoals: SipOptimizerGoal[];
}

const formatCurrency = (value: number | '', prefix = '₹') => {
    const num = typeof value === 'number' ? value : 0;
    if (isNaN(num)) return `${prefix}0`;
    return `${prefix}${num.toLocaleString('en-IN', { maximumFractionDigits: 0 })}`;
};

const formatYears = (years: number) => {
    if (!isFinite(years) || years <= 0 || isNaN(years)) return 'N/A';
    const y = Math.floor(years);
    const m = Math.round((years - y) * 12);
    if (y > 0 && m > 0) return `${y}Y ${m}M`;
    if (y > 0) return `${y}Y`;
    if (m > 0) return `${m}M`;
    return '0M';
}

const roundToNearest100 = (num: number) => {
    return Math.round(num / 100) * 100;
}

export function GoalsBreakdown({ optimizedGoals }: Props) {
  if (!optimizedGoals || optimizedGoals.length === 0) {
    return null;
  }

  return (
    <div className="xl:col-span-2 space-y-8">
        <div className="text-center">
            <h3 className="text-2xl font-bold font-headline text-foreground">Goals Breakdown</h3>
        </div>
      {optimizedGoals.map((goal) => {
          // Correctly calculate the target corpus for the "must invest" scenario based on inflation.
          const inflationRate = goal.name.toLowerCase().includes('education') ? 0.10 : 0.06;
          const expectedCorpusMustInvest = goal.targetCorpus * Math.pow(1 + inflationRate, goal.timeline.required);

          return (
            <div key={goal.id} className="space-y-4">
              <h4 className="font-bold text-xl text-center md:text-left text-primary">{goal.name}</h4>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {/* Card 1: What I am investing */}
                <Card className="border-red-200 bg-red-50/50">
                  <CardHeader className="p-4">
                    <CardTitle className="text-center text-sm font-semibold text-red-700">What I am investing / Month</CardTitle>
                  </CardHeader>
                  <CardContent className="p-4 text-center space-y-2">
                    <div>
                      <p className="text-xs text-muted-foreground">Current SIP</p>
                      <p className="font-bold text-lg">{formatCurrency(goal.investmentStatus.currentInvestment)}</p>
                    </div>
                    <div>
                      <p className="text-xs text-muted-foreground">Time</p>
                      <p className="font-bold text-lg">{formatYears(goal.timeline.current)}</p>
                    </div>
                    <div>
                      <p className="text-xs text-muted-foreground">Goal Amt.</p>
                      <p className="font-bold text-lg">{formatCurrency(goal.potentialCorpus)}</p>
                    </div>
                  </CardContent>
                </Card>

                {/* Card 2: What I must invest */}
                <Card className="border-orange-200 bg-orange-50/50">
                  <CardHeader className="p-4">
                    <CardTitle className="text-center text-sm font-semibold text-orange-700">What I must invest / Month</CardTitle>
                  </CardHeader>
                  <CardContent className="p-4 text-center space-y-2">
                    <div>
                      <p className="text-xs text-muted-foreground">Required SIP</p>
                      <p className="font-bold text-lg">{formatCurrency(roundToNearest100(goal.investmentStatus.requiredInvestment))}</p>
                    </div>
                    <div>
                      <p className="text-xs text-muted-foreground">Time</p>
                      <p className="font-bold text-lg">{formatYears(goal.timeline.required)}</p>
                    </div>
                    <div>
                      <p className="text-xs text-muted-foreground">Expected Corpus</p>
                      <p className="font-bold text-lg">{formatCurrency(expectedCorpusMustInvest)}</p>
                    </div>
                  </CardContent>
                </Card>

                {/* Card 3: What I can invest */}
                <Card className="border-green-200 bg-green-50/50">
                  <CardHeader className="p-4">
                    <CardTitle className="text-center text-sm font-semibold text-green-700">What I can invest / Month</CardTitle>
                  </CardHeader>
                  <CardContent className="p-4 text-center space-y-2">
                    <div>
                      <p className="text-xs text-muted-foreground">Allocated SIP</p>
                      <p className="font-bold text-lg">{formatCurrency(roundToNearest100(goal.investmentStatus.allocatedInvestment))}</p>
                    </div>
                    <div>
                      <p className="text-xs text-muted-foreground">Time</p>
                      <p className="font-bold text-lg">{formatYears(goal.timeline.potential)}</p>
                    </div>
                    <div>
                      <p className="text-xs text-muted-foreground">Expected Corpus</p>
                      <p className="font-bold text-lg">{formatCurrency(goal.futureValue)}</p>
                    </div>
                  </CardContent>
                </Card>
              </div>
            </div>
          )
      })}
    </div>
  );
}

src/components/planner/IncomeExpensesFor.content:
"use client";

import type { Income, Expense } from '@/lib/types';
import { FormSection } from './FormSection';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Trash2, PlusCircle, HandCoins, PiggyBank } from 'lucide-react';
import { Separator } from '../ui/separator';
import { Label } from '../ui/label';

interface Props {
  incomes: Income[];
  setIncomes: React.Dispatch<React.SetStateAction<Income[]>>;
  expenses: Expense[];
  setExpenses: React.Dispatch<React.SetStateAction<Expense[]>>;
  monthlyCashflow: number;
  yearlyCashflow: number;
}

const incomeSources = ["Salary", "Business", "Rental Income", "Investments", "Other"];
const expenseTypes = ["Rent", "Groceries", "Education", "Insurance Premium", "Utilities", "Clubbing", "Party", "Salary to Househelp", "Other"];

let nextId = 0;

export function IncomeExpensesForm({ incomes, setIncomes, expenses, setExpenses, monthlyCashflow, yearlyCashflow }: Props) {

  const handleUpdate = <T extends Income | Expense>(
    items: T[], 
    setItems: React.Dispatch<React.SetStateAction<T[]>>, 
    id: string, 
    field: keyof T, 
    value: string | number
  ) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handleAdd = <T extends Income | Expense>(
    setItems: React.Dispatch<React.SetStateAction<T[]>>,
    newItem: Omit<T, 'id' | 'otherType'>
  ) => {
     setItems(prevItems => [...prevItems, { ...newItem, id: `new-${nextId++}` } as T]);
  };

  const handleRemove = <T extends Income | Expense>(
    items: T[],
    setItems: React.Dispatch<React.SetStateAction<T[]>>,
    id: string
  ) => {
    setItems(items.filter(item => item.id !== id));
  };

  return (
    <FormSection
      title="Income & Expenses"
      description="Understand your monthly and annual cash flow."
      icon={<HandCoins className="h-6 w-6" />}
    >
      <div className="space-y-6">
        {/* Income Section */}
        <div>
          <h3 className="font-semibold text-lg mb-2 text-green-600">Monthly Income</h3>
          <div className="space-y-3">
            {incomes.map((income) => (
              <div key={income.id} className="p-3 border rounded-md space-y-3">
                <div className="grid grid-cols-1 sm:grid-cols-[1fr_1fr_auto] gap-2 items-center">
                  <Select
                    value={income.source}
                    onValueChange={(value) => handleUpdate(incomes, setIncomes, income.id, 'source', value)}
                  >
                    <SelectTrigger><SelectValue placeholder="Select income source" /></SelectTrigger>
                    <SelectContent>
                      {incomeSources.map(source => <SelectItem key={source} value={source}>{source}</SelectItem>)}
                    </SelectContent>
                  </Select>
                  <Input
                    type="number"
                    placeholder="Amount (₹)"
                    value={income.amount}
                    onChange={(e) => handleUpdate(incomes, setIncomes, income.id, 'amount', e.target.value === '' ? '' : Number(e.target.value))}
                  />
                  <Button variant="ghost" size="icon" onClick={() => handleRemove(incomes, setIncomes, income.id)} className="text-destructive">
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
                 {income.source === 'Other' && (
                  <div className="space-y-2 animate-in fade-in-50">
                    <Label htmlFor={`income-other-${income.id}`}>Please specify</Label>
                    <Input
                      id={`income-other-${income.id}`}
                      placeholder="e.g., Freelance"
                      value={income.otherType || ''}
                      onChange={(e) => handleUpdate(incomes, setIncomes, income.id, 'otherType', e.target.value)}
                    />
                  </div>
                )}
              </div>
            ))}
          </div>
          <Button variant="outline" size="sm" className="mt-3" onClick={() => handleAdd(setIncomes, { source: '', amount: '' })}>
            <PlusCircle className="mr-2 h-4 w-4" /> Add Income
          </Button>
        </div>

        {/* Expenses Section */}
        <div>
          <h3 className="font-semibold text-lg mb-2 text-red-600">Monthly Expenses</h3>
          <div className="space-y-3">
            {expenses.map((expense) => (
              <div key={expense.id} className="p-3 border rounded-md space-y-3">
                <div className="grid grid-cols-1 sm:grid-cols-[1fr_1fr_auto] gap-2 items-center">
                  <Select
                    value={expense.type}
                    onValueChange={(value) => handleUpdate(expenses, setExpenses, expense.id, 'type', value)}
                  >
                    <SelectTrigger><SelectValue placeholder="Select expense type" /></SelectTrigger>
                    <SelectContent>
                      {expenseTypes.map(type => <SelectItem key={type} value={type}>{type}</SelectItem>)}
                    </SelectContent>
                  </Select>
                  <Input
                    type="number"
                    placeholder="Amount (₹)"
                    value={expense.amount}
                    onChange={(e) => handleUpdate(expenses, setExpenses, expense.id, 'amount', e.target.value === '' ? '' : Number(e.target.value))}
                  />
                  <Button variant="ghost" size="icon" onClick={() => handleRemove(expenses, setExpenses, expense.id)} className="text-destructive">
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
                {expense.type === 'Other' && (
                  <div className="space-y-2 animate-in fade-in-50">
                    <Label htmlFor={`expense-other-${expense.id}`}>Please specify</Label>
                    <Input
                      id={`expense-other-${expense.id}`}
                      placeholder="e.g., Travel"
                      value={expense.otherType || ''}
                      onChange={(e) => handleUpdate(expenses, setExpenses, expense.id, 'otherType', e.target.value)}
                    />
                  </div>
                )}
              </div>
            ))}
          </div>
          <Button variant="outline" size="sm" className="mt-3" onClick={() => handleAdd(setExpenses, { type: '', amount: '' })}>
            <PlusCircle className="mr-2 h-4 w-4" /> Add Expense
          </Button>
        </div>

        {/* Cashflow Display */}
        <div className="bg-primary/10 p-4 rounded-lg space-y-3">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <PiggyBank className="h-7 w-7 text-primary" />
                    <span className="font-semibold text-primary">Monthly Cashflow</span>
                </div>
                <span className={`font-bold text-xl font-headline ${monthlyCashflow >= 0 ? 'text-primary' : 'text-destructive'}`}>
                    ₹{monthlyCashflow.toLocaleString('en-IN', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}
                </span>
            </div>
            <Separator />
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <PiggyBank className="h-7 w-7 text-primary/70" />
                    <span className="font-semibold text-primary/80">Yearly Cashflow</span>
                </div>
                <span className={`font-bold text-xl font-headline ${yearlyCashflow >= 0 ? 'text-primary/80' : 'text-destructive'}`}>
                    ₹{yearlyCashflow.toLocaleString('en-IN', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}
                </span>
            </div>
        </div>
      </div>
    </FormSection>
  );
}

