      );
    }

    return NextResponse.json({ data: reportData });
  } catch (error: any) {
    console.error('Error in get-report API:', error);
    return NextResponse.json(
      { error: error.message || 'Failed to retrieve report' },
      { status: 500 }
    );
  }
}

